// Regenerates src/content/theology/courses/index.ts so every course file is bundled.
// Run: node scripts/theology-index.mjs
import fs from "node:fs";
import path from "node:path";
const dir = path.resolve("src/content/theology/courses");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const name = (f) => "c_" + f.replace(/\.json$/, "").replace(/[^a-z0-9]/gi, "_");
const out = [
  "// Generated by scripts/theology-index.mjs. Do not edit by hand.",
  'import type { TheologyCourse } from "../types";',
  ...files.map((f) => `import ${name(f)} from "./${f}";`),
  "",
  `export const theologyCourses = [${files.map(name).join(", ")}] as TheologyCourse[];`,
  "",
].join("\n");
fs.writeFileSync(path.join(dir, "index.ts"), out);
console.log(`Indexed ${files.length} course files.`);
